"""Pin the version and time in the "Generated by bust" line, so that generated
files match the goldens whatever the bust version and the time of the run."""

import pytest


@pytest.fixture(autouse=True)
def _fixed_generated_by(monkeypatch):
    monkeypatch.setenv("SOURCE_DATE_EPOCH", "0")
    monkeypatch.setattr("bust.jinja_utils.environment.__VERSION__", "1.0.0-dev")
